import{_ as e,a,c as t}from"./chunks/framework.BkXmWmgX.js";const p=JSON.parse('{"title":"Radix UI는 언제 사용해야 하는가 | OTW for FE","titleTemplate":false,"description":"","frontmatter":{"layout":"post","title":"OTW for FE","titleTemplate":false,"lang":"ko"},"headers":[],"params":{"id":"30ce548d-8a8e-8030-b412-f3e2f3b927d0","title":"Radix UI는 언제 사용해야 하는가","date":"2026-02-25","coverUrl":"/kudzu-based-bench/assets/notion/908c53349e9eed9b.png","html":"<h1 data-notion-block-id=\\"30ce548d-8a8e-805b-8fd6-eb61f897fe32\\">Beyond the Article: 한 걸음 더</h1><h2 data-notion-block-id=\\"30ce548d-8a8e-802b-a313-ecdcd653218e\\" id=\\"30ce548d-8a8e-802b-a313-ecdcd653218e\\">Radix UI는 언제 사용해야 하는가</h2><a href=\\"https://shadcnspace.com/blog/radix-ui-vs-base-ui\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shadcnspace.com/blog/radix-ui-vs-base-ui</a><p data-notion-block-id=\\"311e548d-8a8e-8096-b702-ec698d9f93e2\\">Radix UI가 개발이 멈췄다는 소식을 듣고 그를 어느정도 계승하고 있다는 Base UI로 옮겨갔다는 소식을 많이 듣습니다. 이 글에서는 그럼에도 Radix UI가 주는 장점이 있음을 Base UI와 비교해서 소개합니다. 전체적으로 Base UI가 개발자에게 선택지를 많이주지만 너무 많은 선택지를 주기에 빠르게 구축하기에 부족함을 의미하고, Radix UI는 주관적인(\\"opnionated\\") 선택지를 제공하지만, 그만큼 빠르게 구축할 수있음을 <code>&#x3C;Dialog></code>컴포넌트를 기준으로 소개하고 있습니다. 이외에도 React Aria나 Ark UI같은 선택지도 있으므로, 선택을 신중히 해야 할 것 같습니다.</p><h2 data-notion-block-id=\\"311e548d-8a8e-8040-b425-e613c8c6db2c\\" id=\\"311e548d-8a8e-8040-b425-e613c8c6db2c\\"><code>React.FC&#x3C;></code>를 포기해라</h2><a href=\\"https://engineering.gusto.com/the-journey-to-a-safer-frontend-why-we-removed-react-fc-095ff0b3e2e4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://engineering.gusto.com/the-journey-to-a-safer-frontend-why-we-removed-react-fc-095ff0b3e2e4</a><p data-notion-block-id=\\"30ce548d-8a8e-8010-aab8-d342b701aeef\\"><code>React.FC&#x3C;></code>제너릭을 왜 포기했는지, 그리고 어떻게 바꾸는 것이 어떤 이점을 가져오는지 소개합니다. 그리고 어떻게 바꾸는 작업을 자동화하고 사용하지 않는 props나 타입 불일치를 해결했는지까지 소개합니다. 관련해서 <a href=\\"https://react-typescript-cheatsheet.netlify.app/docs/basic/getting-started/function_components\\">권장사항 Cheatsheet</a>이나 <a href=\\"https://github.com/gndelia/codemod-replace-react-fc-typescript\\">codemod</a> 또한 참고하시면 좋습니다.</p><h2 data-notion-block-id=\\"30ce548d-8a8e-80ab-a0ee-fcd199b6d304\\" id=\\"30ce548d-8a8e-80ab-a0ee-fcd199b6d304\\">JS 중심 접근방식은 지속가능하지 않다</h2><a href=\\"https://sgom.es/posts/2026-02-13-js-heavy-approaches-are-not-compatible-with-long-term-performance-goals/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sgom.es/posts/2026-02-13-js-heavy-approaches-are-not-compatible-with-long-term-performance-goals/</a><p data-notion-block-id=\\"311e548d-8a8e-8062-b94d-ca3ad02bd8ea\\">JS 중심 접근방식의 허점을 살펴보고, 그의 중심에 있는 React가 사용할 가치가 있는지 주관적인 의견을 소개하는 글입니다. 물론 React가 주는 생태계의 이점과 프론트엔드를 주도하고 있음을 무시할 수는 없지만, <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#279e548d-8a8e-80bc-bcfb-ea405e329206\\">리액트에 숨겨진 비용</a>에서도 말했듯이 안정성과 성능상 단점이 있다는 것은 무시할 수 없는 부분이긴 합니다. 좋은 절충점을 찾는 것이 좋아보입니다.</p><h2 data-notion-block-id=\\"311e548d-8a8e-8029-a83a-cd93ec9fddbb\\" id=\\"311e548d-8a8e-8029-a83a-cd93ec9fddbb\\">이제는 CSS5의 시대입니다.</h2><a href=\\"https://modern-css.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://modern-css.com/</a><p data-notion-block-id=\\"30ce548d-8a8e-804d-a992-fcc7dd5616bd\\">CSS5라고 칭할 정도로 Baseline에서 수많은 CSS가 모던 브라우저에 많이 구현되었지만, 우리는 그 CSS를 사용하고 있지 않습니다(그리고 아직도 CSS3라고 칭하고 있죠 😢). 이 사이트에서는 CSS5를 중심으로 최신 CSS를 사용하는 방법을 소개합니다.</p><h1 data-notion-block-id=\\"30ce548d-8a8e-8089-81c8-ebfd0b03b562\\">Straight to the Article: 빛나는 인사이트</h1><h2 data-notion-block-id=\\"311e548d-8a8e-80c7-aef1-c78e8faaed7d\\" id=\\"311e548d-8a8e-80c7-aef1-c78e8faaed7d\\">Streaming API 개선기</h2><a href=\\"https://vercel.com/blog/we-ralph-wiggumed-webstreams-to-make-them-10x-faster\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/we-ralph-wiggumed-webstreams-to-make-them-10x-faster</a><p data-notion-block-id=\\"311e548d-8a8e-8086-a9d3-e942e5a327e1\\">왜 표준에 해당하는 Streaming API가 기존의 Streaming API보다 느린지 소개하고, 기존의 Streaming API를 기반으로 표준 Streaming API를 구현하여 속도를 빠르게 만들었다는 글입니다.</p><h2 data-notion-block-id=\\"311e548d-8a8e-8029-b020-ea339dbeb14b\\" id=\\"311e548d-8a8e-8029-b020-ea339dbeb14b\\">Tanstack Query에서 추상화하기</h2><a href=\\"https://tkdodo.eu/blog/creating-query-abstractions\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/creating-query-abstractions</a><p data-notion-block-id=\\"311e548d-8a8e-80c7-9966-d21fb6aaf39e\\">수많은 사람이 Tanstack Query를 사용할텐데, 이 때 타입 불일치나 Custom Hook의 추상화 어려움을 queryOption API를 사용하면 해결할 수 있다는 간단한 글입니다.</p><h2 data-notion-block-id=\\"311e548d-8a8e-808c-8a47-cd998280abe0\\" id=\\"311e548d-8a8e-808c-8a47-cd998280abe0\\">Node.js에서의 포인터 압축</h2><a href=\\"https://blog.platformatic.dev/we-cut-nodejs-memory-in-half\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.platformatic.dev/we-cut-nodejs-memory-in-half</a><p data-notion-block-id=\\"30fe548d-8a8e-8074-a38d-ea4df5a854b8\\">Node.js에서 포인터 압축 기능을 활성화했을 경우의 이점을 벤치마크 기반으로 소개하는 글입니다. 그와 함께 어떻게 포인터 압축 기능을 어떻게 사용하는지 알려주고 있습니다.</p><h2 data-notion-block-id=\\"30ce548d-8a8e-80de-b97c-e9dd69b11a3e\\" id=\\"30ce548d-8a8e-80de-b97c-e9dd69b11a3e\\">TypeScript 제네릭 실사용 사례</h2><a href=\\"https://frontendmasters.com/blog/fun-with-typescript-generics/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/fun-with-typescript-generics/</a><h2 data-notion-block-id=\\"30ce548d-8a8e-80f9-8c5f-d5c6b811dfff\\" id=\\"30ce548d-8a8e-80f9-8c5f-d5c6b811dfff\\">Node.js에서 <code>fetch()</code>사용법</h2><a href=\\"https://nodejsdesignpatterns.com/blog/nodejs-http-request/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejsdesignpatterns.com/blog/nodejs-http-request/</a><h2 data-notion-block-id=\\"311e548d-8a8e-80b6-beb4-e2f344d992d2\\" id=\\"311e548d-8a8e-80b6-beb4-e2f344d992d2\\">AI 기반 제품에는 어떤 UX가 필요할까</h2><a href=\\"https://www.smashingmagazine.com/2026/02/designing-agentic-ai-practical-ux-patterns/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2026/02/designing-agentic-ai-practical-ux-patterns/</a><h1 data-notion-block-id=\\"30ce548d-8a8e-8047-a511-c2637b2a5b4d\\">Fresh Finds: 놓치지 말아야 할 소식</h1><a href=\\"https://blackboard.sh/blog/electrobun-v1/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blackboard.sh/blog/electrobun-v1/</a><p data-notion-block-id=\\"30fe548d-8a8e-8000-83de-ca6881cdb22e\\">Electron과 Tauri를 왜 포기했고, 그의 대체인 Electrobun을 만들었는지 소개하는 글입니다.</p><a href=\\"https://styled-components.com/releases#styled-components@6.3.7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://styled-components.com/releases#styled-components@6.3.7</a><p data-notion-block-id=\\"30ce548d-8a8e-807a-9d22-c9abe8866d43\\">최근 RSC를 지원하게 되면서, styled-components가 그저 maintaining모드에서 다시 활발하게 개발되고 있음으로 바뀌었음을 보여주고 있습니다.</p><a href=\\"https://tmikov.blogspot.com/2026/02/webassembly-comes-to-hermes_01829874520.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tmikov.blogspot.com/2026/02/webassembly-comes-to-hermes_01829874520.html</a><p data-notion-block-id=\\"30fe548d-8a8e-8048-b2d3-e2f50624eb92\\">WASM파일을 Hermes컴파일할 수 있음을 소개하는 글입니다.</p><a href=\\"https://tiktok.github.io/sparkling/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tiktok.github.io/sparkling/</a><p data-notion-block-id=\\"30fe548d-8a8e-8090-ba68-e33bde3cd43e\\">Lynx 라이브러리를 기반으로 빠르게 앱을 만들 수 있는 프레임워크인 Sparkling입니다. React Native의 대항마로서 좋은 상대가 될지 주목해볼만 할 것 같습니다.</p><a href=\\"https://www.repoflow.io/blog/node-js-vs-deno-vs-bun-performance-benchmarks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.repoflow.io/blog/node-js-vs-deno-vs-bun-performance-benchmarks</a><p data-notion-block-id=\\"30fe548d-8a8e-809b-a5d5-e5d606c7ddd9\\">Node.js/Deno/Bun의 여러 상황에서의 네이티브 기능을 테스트한 벤치마크입니다.</p><a href=\\"https://tanstack.com/start/latest/docs/framework/react/guide/import-protection\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/start/latest/docs/framework/react/guide/import-protection</a><p data-notion-block-id=\\"30fe548d-8a8e-80a2-9307-eb0d8db017cf\\">Tanstack Start에서 <code>\\"import server-only\\"</code>와 같은 import ~ 패턴을 구현했음을 소개하는 글입니다.</p><a href=\\"https://www.react.doctor/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.react.doctor/</a><p data-notion-block-id=\\"311e548d-8a8e-8064-8df9-ecbaa9114165\\">React에서 안티패턴을 찾아주는 도구인 React doctor입니다.</p>"},"relativePath":"news/post/30ce548d-8a8e-8030-b412-f3e2f3b927d0.md","filePath":"news/post/[id].md"}'),o={name:"news/post/30ce548d-8a8e-8030-b412-f3e2f3b927d0.md"};function r(d,c,n,s,i,b){return a(),t("div")}const f=e(o,[["render",r]]);export{p as __pageData,f as default};
